-- Wild Atlantic Glamping Reviews (Campsite c0000000-0000-0000-0000-000000000001)
INSERT INTO reviews (id, booking_id, campsite_id, user_id, rating, cleanliness_rating, facilities_rating, location_rating, value_rating, comment, owner_response, helpful_count, created_at, updated_at) VALUES
('e0000000-0000-0000-0001-000000000001', 'b0000000-0000-0000-0001-000000000001', 'c0000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001', 5, 5, 5, 5, 5, 'Absolutely magical anniversary getaway! The ocean view dome exceeded all expectations. Falling asleep to the sound of waves and waking up to stunning Atlantic views was incredible. The hot tub under the stars was the highlight. Sean and his team made everything perfect.', 'Thank you so much Ciara! It was our pleasure to help make your anniversary special. We hope to welcome you back soon!', 12, NOW() - INTERVAL '5 months 18 days', NOW() - INTERVAL '5 months 10 days'),

('e0000000-0000-0000-0001-000000000002', 'b0000000-0000-0000-0001-000000000002', 'c0000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000002', 5, 5, 5, 5, 4, 'Perfect location for photography! Captured some amazing sunset shots. The dome was spotlessly clean and the aromatherapy kit was a nice touch. Only minor note is the price is on the higher end, but you get what you pay for.', 'Thanks Conor! Your photos were stunning - feel free to share them with us. The Wild Atlantic Way sunsets are truly special.', 8, NOW() - INTERVAL '5 months 13 days', NOW() - INTERVAL '5 months 8 days'),

('e0000000-0000-0000-0002-000000000001', 'b0000000-0000-0000-0002-000000000001', 'c0000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000005', 5, 5, 5, 5, 5, 'Our third visit and it never disappoints! The Stargazer Dome is perfect for watching the night sky. Kids loved spotting shooting stars. Breakfast hamper was delicious with local produce. Already planning our next trip!', 'Welcome back Niamh! So glad the family enjoyed stargazing. See you again soon!', 15, NOW() - INTERVAL '4 months 23 days', NOW() - INTERVAL '4 months 18 days'),

('e0000000-0000-0000-0002-000000000002', 'b0000000-0000-0000-0002-000000000004', 'c0000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000011', 4, 5, 4, 5, 4, 'Beautiful location and luxurious domes. The honeymoon suite was romantic and well-equipped. Hot tub was amazing. Slight issue with wifi connectivity but staff resolved it quickly. Would recommend for special occasions.', 'Thank you Aisling! We apologise for the wifi hiccup - we have since upgraded our infrastructure. Hope to see you again!', 6, NOW() - INTERVAL '4 months 8 days', NOW() - INTERVAL '4 months 3 days'),

('e0000000-0000-0000-0003-000000000001', 'b0000000-0000-0000-0003-000000000001', 'c0000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000002', 5, 5, 5, 5, 5, 'Autumn photography trip was perfect! The moody Atlantic skies made for incredible shots. Stargazing kit rental was a great addition. Highly recommend for anyone who loves nature and photography.', NULL, 9, NOW() - INTERVAL '3 months 20 days', NOW() - INTERVAL '3 months 18 days'),

('e0000000-0000-0000-0004-000000000001', 'b0000000-0000-0000-0004-000000000001', 'c0000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000018', 5, 5, 5, 5, 5, 'Second anniversary here and somehow even better than the first! The champagne welcome pack was a lovely touch. Staff remembered us from last year. This place is truly special.', 'Happy anniversary again Grainne! We love welcoming returning guests. Your loyalty means the world to us.', 11, NOW() - INTERVAL '2 months 15 days', NOW() - INTERVAL '2 months 10 days'),

('e0000000-0000-0000-0005-000000000001', 'b0000000-0000-0000-0005-000000000001', 'c0000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000005', 5, 5, 5, 5, 4, 'Winter storm watching from the dome was incredible! Cozy inside while the Atlantic raged outside. Breakfast hampers were perfect for not wanting to leave the warmth. Unique experience!', 'Thank you for braving the winter weather with us! Storm season here is quite something special.', 7, NOW() - INTERVAL '1 month 17 days', NOW() - INTERVAL '1 month 12 days');

-- Donegal Coastal Camp Reviews (Campsite c0000000-0000-0000-0000-000000000002)
INSERT INTO reviews (id, booking_id, campsite_id, user_id, rating, cleanliness_rating, facilities_rating, location_rating, value_rating, comment, owner_response, helpful_count, created_at, updated_at) VALUES
('e0000000-0000-0000-0001-000000000003', 'b0000000-0000-0000-0001-000000000004', 'c0000000-0000-0000-0000-000000000002', 'a1000000-0000-0000-0000-000000000003', 5, 4, 4, 5, 5, 'Perfect family camping holiday! The beach is literally steps away. Kids spent all day building sandcastles and playing in the waves. Facilities are clean and well-maintained. Fish & chips from the on-site takeaway were delicious. Great value for money!', 'So glad the family had a great time Aoife! The beach is definitely our biggest asset. Hope to see you all again next summer!', 18, NOW() - INTERVAL '5 months 21 days', NOW() - INTERVAL '5 months 15 days'),

('e0000000-0000-0000-0002-000000000003', 'b0000000-0000-0000-0002-000000000005', 'c0000000-0000-0000-0000-000000000002', 'a1000000-0000-0000-0000-000000000012', 4, 4, 4, 5, 5, 'Week-long beach holiday was exactly what we needed. The pitch location was great with sea views. Showers could use an update but everything was clean. The shop on site saved us a trip to town. Kids want to come back!', 'Thanks Cillian! We are planning shower facility upgrades for next season. Looking forward to welcoming your family back!', 10, NOW() - INTERVAL '4 months 20 days', NOW() - INTERVAL '4 months 15 days'),

('e0000000-0000-0000-0002-000000000004', 'b0000000-0000-0000-0002-000000000006', 'c0000000-0000-0000-0000-000000000002', 'a1000000-0000-0000-0000-000000000001', 4, 4, 4, 5, 5, 'Nice and affordable camping right by the beach. The firewood bundles were great for evening campfires. Beach equipment hire was convenient for the kids. Good basic facilities - nothing fancy but everything you need.', NULL, 5, NOW() - INTERVAL '4 months 13 days', NOW() - INTERVAL '4 months 10 days');

-- Sligo Surf Camp Reviews (Campsite c0000000-0000-0000-0000-000000000003)
INSERT INTO reviews (id, booking_id, campsite_id, user_id, rating, cleanliness_rating, facilities_rating, location_rating, value_rating, comment, owner_response, helpful_count, created_at, updated_at) VALUES
('e0000000-0000-0000-0001-000000000004', 'b0000000-0000-0000-0001-000000000006', 'c0000000-0000-0000-0000-000000000003', 'a1000000-0000-0000-0000-000000000004', 5, 4, 5, 5, 5, 'Best surf trip ever! Strandhill waves were pumping. Equipment rental made it so easy - boards and wetsuits in great condition. The communal fire pit vibe in the evenings was brilliant. Met fellow surfers from all over. Will definitely be back!', 'Stoked you caught good waves Sean! The surf community here is what makes this place special. See you in the lineup!', 22, NOW() - INTERVAL '5 months 28 days', NOW() - INTERVAL '5 months 20 days'),

('e0000000-0000-0000-0002-000000000005', 'b0000000-0000-0000-0002-000000000008', 'c0000000-0000-0000-0000-000000000003', 'a1000000-0000-0000-0000-000000000004', 5, 4, 5, 5, 5, 'Back for another week of waves! The surf lesson was excellent for my girlfriend who was learning. The instructors are patient and knowledgeable. Beach pod upgrade was worth it for the comfort. Great breakfast at the surf shack cafe.', 'Always great to have you back Sean! Glad your girlfriend enjoyed the lessons. The summer swells were epic this year!', 14, NOW() - INTERVAL '4 months 22 days', NOW() - INTERVAL '4 months 18 days'),

('e0000000-0000-0000-0002-000000000006', 'b0000000-0000-0000-0002-000000000009', 'c0000000-0000-0000-0000-000000000003', 'a1000000-0000-0000-0000-000000000020', 4, 4, 4, 5, 5, 'First time surfing and loved it! The group lesson was fun and not intimidating. Beach location is perfect - you can literally walk to the water. Facilities are basic but clean. Perfect for budget-conscious surf trips.', 'So happy you caught the surfing bug Saoirse! Once you start, you cannot stop. Hope to see you progress next time!', 8, NOW() - INTERVAL '4 months 16 days', NOW() - INTERVAL '4 months 12 days'),

('e0000000-0000-0000-0003-000000000002', 'b0000000-0000-0000-0003-000000000004', 'c0000000-0000-0000-0000-000000000003', 'a1000000-0000-0000-0000-000000000004', 5, 4, 5, 5, 5, 'Autumn swells did not disappoint! Empty lineup and solid waves. Equipment still in great shape end of season. The Beach Pod is cozy when it gets cold. Love this place - third trip this year!', 'Legend! Thanks for the continued support Sean. Autumn swells are our little secret - shhh!', 11, NOW() - INTERVAL '3 months 23 days', NOW() - INTERVAL '3 months 20 days');

-- Galway Bay Guesthouse Reviews (Campsite c0000000-0000-0000-0000-000000000004)
INSERT INTO reviews (id, booking_id, campsite_id, user_id, rating, cleanliness_rating, facilities_rating, location_rating, value_rating, comment, owner_response, helpful_count, created_at, updated_at) VALUES
('e0000000-0000-0000-0001-000000000005', 'b0000000-0000-0000-0001-000000000008', 'c0000000-0000-0000-0000-000000000004', 'a1000000-0000-0000-0000-000000000013', 5, 5, 5, 5, 4, 'What a wonderful B&B! Mary was the perfect host - so welcoming and full of local recommendations. The Full Irish Breakfast was the best I have had in Ireland. Sea view room was gorgeous. Walking distance to Salthill. Only wish we had booked longer!', 'Thank you Emma! It was lovely having you. Americans always appreciate a proper Irish breakfast! Come back anytime.', 16, NOW() - INTERVAL '5 months 16 days', NOW() - INTERVAL '5 months 10 days'),

('e0000000-0000-0000-0002-000000000007', 'b0000000-0000-0000-0002-000000000011', 'c0000000-0000-0000-0000-000000000004', 'a1000000-0000-0000-0000-000000000017', 5, 5, 5, 5, 4, 'Visited during the Galway Arts Festival and this was the perfect base. The afternoon tea was exceptional - homemade scones to die for! Mary helped us get tickets to sold-out shows. The location on Salthill is unbeatable.', 'So glad you enjoyed the festival Tadhg! The Arts Festival is such a special time in Galway. Your fishing recommendations were spot on too!', 12, NOW() - INTERVAL '4 months 20 days', NOW() - INTERVAL '4 months 15 days'),

('e0000000-0000-0000-0003-000000000003', 'b0000000-0000-0000-0003-000000000006', 'c0000000-0000-0000-0000-000000000004', 'a1000000-0000-0000-0000-000000000009', 5, 5, 5, 5, 5, 'Lovely culture trip to Galway. The guesthouse has such a homely feel. Mary is incredibly knowledgeable about local history and culture. Breakfast portions are generous! Great base for exploring Connemara. Highly recommend.', NULL, 9, NOW() - INTERVAL '3 months 15 days', NOW() - INTERVAL '3 months 12 days'),

('e0000000-0000-0000-0004-000000000002', 'b0000000-0000-0000-0004-000000000003', 'c0000000-0000-0000-0000-000000000004', 'a1000000-0000-0000-0000-000000000013', 5, 5, 5, 5, 4, 'Back again for the October bank holiday! Mary remembered us from the summer and had our favourite room ready. The packed lunches for our day trips were so convenient. This place feels like visiting a friend.', 'Emma! So lovely to have you back. You are always welcome here. Safe travels back to the States!', 7, NOW() - INTERVAL '2 months 20 days', NOW() - INTERVAL '2 months 15 days'),

('e0000000-0000-0000-0005-000000000002', 'b0000000-0000-0000-0005-000000000003', 'c0000000-0000-0000-0000-000000000004', 'a1000000-0000-0000-0000-000000000014', 4, 5, 4, 5, 4, 'Comfortable and welcoming B&B. The deluxe king room was spacious. Mary is a wonderful host. Breakfast was excellent. Minor point - the heating took a while to warm up on cold November mornings. Otherwise perfect!', 'Thank you Hans! We have adjusted the heating timer based on your feedback. Appreciate you taking the time to let us know!', 4, NOW() - INTERVAL '1 month 20 days', NOW() - INTERVAL '1 month 15 days');

-- West Cork Eco Retreat Reviews (Campsite c0000000-0000-0000-0000-000000000006)
INSERT INTO reviews (id, booking_id, campsite_id, user_id, rating, cleanliness_rating, facilities_rating, location_rating, value_rating, comment, owner_response, helpful_count, created_at, updated_at) VALUES
('e0000000-0000-0000-0001-000000000006', 'b0000000-0000-0000-0001-000000000010', 'c0000000-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000016', 5, 5, 5, 5, 5, 'This eco retreat is everything I dreamed of! The treehouse was magical - waking up in the canopy was surreal. Morning yoga sessions were transformative. The organic breakfast is farm-fresh perfection. Aoife has created something truly special here.', 'Namaste Fionnuala! Your energy in the yoga sessions was wonderful. The garden misses you already. Come back for our autumn wellness week!', 24, NOW() - INTERVAL '5 months 8 days', NOW() - INTERVAL '5 months 2 days'),

('e0000000-0000-0000-0002-000000000008', 'b0000000-0000-0000-0002-000000000015', 'c0000000-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000007', 5, 5, 5, 5, 4, 'The Willow Treehouse exceeded expectations! E-bikes made exploring the area so easy. The organic gardens are beautiful and you can see where your breakfast comes from. Only minor note - treehouse ladder is tricky with luggage. Pack light!', 'Great tip about the luggage Sinead! We now offer a pulley system for bags. Thanks for the feedback and glad you loved the e-bikes!', 15, NOW() - INTERVAL '4 months 22 days', NOW() - INTERVAL '4 months 18 days'),

('e0000000-0000-0000-0002-000000000009', 'b0000000-0000-0000-0002-000000000016', 'c0000000-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000016', 5, 5, 5, 5, 5, 'Yurt yoga retreat was life-changing! Four days of wellness, organic food, and nature immersion. The garden workshop taught me so much about sustainable living. Already planning my next visit.', 'Your dedication to the practice was inspiring Fionnuala! Looking forward to having you back for our winter solstice retreat.', 18, NOW() - INTERVAL '4 months 16 days', NOW() - INTERVAL '4 months 12 days'),

('e0000000-0000-0000-0003-000000000004', 'b0000000-0000-0000-0003-000000000009', 'c0000000-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000016', 5, 5, 5, 5, 5, 'Third visit this year! Autumn colours in the oak treehouse were stunning. Each season here offers something different. The community of like-minded eco-conscious guests makes this place extra special.', 'We should give you a loyalty card at this point Fionnuala! Your enthusiasm for our mission means so much. See you in winter!', 12, NOW() - INTERVAL '3 months 19 days', NOW() - INTERVAL '3 months 15 days'),

('e0000000-0000-0000-0004-000000000003', 'b0000000-0000-0000-0004-000000000005', 'c0000000-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000016', 5, 5, 5, 5, 5, 'October treehouse stay was absolutely magical. Misty mornings, colourful leaves, cozy evenings by candlelight. The e-bike tour through autumn Glengarriff was unforgettable. This place has my heart.', NULL, 10, NOW() - INTERVAL '2 months 16 days', NOW() - INTERVAL '2 months 12 days'),

('e0000000-0000-0000-0005-000000000003', 'b0000000-0000-0000-0005-000000000006', 'c0000000-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000016', 5, 5, 5, 5, 5, 'Winter wellness in the yurt was exactly what I needed before the holiday chaos. Hot water bottles provided, organic soups, gentle yoga... Pure restoration. Thank you Aoife and team!', 'Your dedication to self-care is admirable Fionnuala! Rest well and see you in the new year!', 8, NOW() - INTERVAL '1 month 12 days', NOW() - INTERVAL '1 month 8 days');

-- Wicklow Woodland Camp Reviews (Campsite c0000000-0000-0000-0000-000000000007)
INSERT INTO reviews (id, booking_id, campsite_id, user_id, rating, cleanliness_rating, facilities_rating, location_rating, value_rating, comment, owner_response, helpful_count, created_at, updated_at) VALUES
('e0000000-0000-0000-0001-000000000007', 'b0000000-0000-0000-0001-000000000011', 'c0000000-0000-0000-0000-000000000007', 'a1000000-0000-0000-0000-000000000003', 4, 4, 4, 5, 5, 'Great family camping in the woods! Kids loved the nature trails and making s''mores by the campfire. Close to Glendalough which was a bonus. Basic facilities but clean and well-maintained. Excellent value for families.', 'Thanks Aoife! So glad the kids enjoyed the woods. The s''mores kits are always a hit! See you again next summer.', 14, NOW() - INTERVAL '5 months 5 days', NOW() - INTERVAL '5 months'),

('e0000000-0000-0000-0002-000000000010', 'b0000000-0000-0000-0002-000000000018', 'c0000000-0000-0000-0000-000000000007', 'a1000000-0000-0000-0000-000000000003', 4, 4, 4, 5, 5, 'Woodland pod was perfect for our family. More comfortable than tent camping but still feels like you are in nature. Kids spotted deer in the morning! The BBQ pack was convenient. Would recommend for families wanting a comfortable camping experience.', 'Deer sightings are always special! Thanks for choosing the woodland pod. Great to have the family back!', 10, NOW() - INTERVAL '4 months 19 days', NOW() - INTERVAL '4 months 15 days'),

('e0000000-0000-0000-0002-000000000011', 'b0000000-0000-0000-0002-000000000019', 'c0000000-0000-0000-0000-000000000007', 'a1000000-0000-0000-0000-000000000018', 5, 5, 4, 5, 5, 'Romantic tree pod getaway! So peaceful in the woods. Woke up to birdsong. The elevated position gives you amazing forest views. Perfect for couples wanting to disconnect. No wifi was actually a blessing!', NULL, 7, NOW() - INTERVAL '4 months 8 days', NOW() - INTERVAL '4 months 5 days'),

('e0000000-0000-0000-0004-000000000004', 'b0000000-0000-0000-0004-000000000006', 'c0000000-0000-0000-0000-000000000007', 'a1000000-0000-0000-0000-000000000003', 4, 4, 4, 5, 5, 'Halloween camping was brilliant! The woods were spooky in a fun way. Kids loved the themed decorations. Campfire with hot chocolate on cold October nights. Great family memories made here.', 'The Halloween decorations were a team effort! So happy the kids enjoyed the spooky atmosphere. Boo! See you next year!', 11, NOW() - INTERVAL '1 month 28 days', NOW() - INTERVAL '1 month 25 days');

-- Ring of Kerry Glamping Reviews (Campsite c0000000-0000-0000-0000-000000000008)
INSERT INTO reviews (id, booking_id, campsite_id, user_id, rating, cleanliness_rating, facilities_rating, location_rating, value_rating, comment, owner_response, helpful_count, created_at, updated_at) VALUES
('e0000000-0000-0000-0001-000000000008', 'b0000000-0000-0000-0001-000000000012', 'c0000000-0000-0000-0000-000000000008', 'a1000000-0000-0000-0000-000000000007', 5, 5, 5, 5, 5, 'Safari tent glamping at its finest! The location in Killarney National Park is unbeatable. Wood-burning stove kept us toasty. BBQ pack meats were excellent quality. The bike hire was perfect for exploring the Ring of Kerry. Absolute dream trip!', 'Thank you Sinead! The park location is indeed special. Glad you made the most of the bikes - the views along the Ring are spectacular!', 19, NOW() - INTERVAL '5 months 18 days', NOW() - INTERVAL '5 months 12 days'),

('e0000000-0000-0000-0002-000000000012', 'b0000000-0000-0000-0002-000000000020', 'c0000000-0000-0000-0000-000000000008', 'a1000000-0000-0000-0000-000000000011', 5, 5, 5, 5, 4, 'August Ring of Kerry tour was magical. The safari tent is spacious and beautifully furnished. Breakfast baskets were delicious - loved the local honey. Kayak experience on the lakes was a highlight. Slightly pricey but worth every penny.', 'Thank you Aisling! The kayak experience is one of our most popular extras. Kerry honey is indeed special!', 13, NOW() - INTERVAL '4 months 22 days', NOW() - INTERVAL '4 months 18 days'),

('e0000000-0000-0000-0002-000000000013', 'b0000000-0000-0000-0002-000000000021', 'c0000000-0000-0000-0000-000000000008', 'a1000000-0000-0000-0000-000000000012', 5, 5, 5, 5, 5, 'Extended family trip in the Mountain Safari Tent. Fit all 6 of us comfortably. The outdoor deck with mountain views was perfect for evening BBQs. Kids loved exploring the national park. Patrick was an excellent host.', 'Wonderful having the whole family Cillian! The Mountain tent is perfect for larger groups. Great to see three generations enjoying the outdoors together!', 16, NOW() - INTERVAL '4 months 13 days', NOW() - INTERVAL '4 months 10 days'),

('e0000000-0000-0000-0003-000000000005', 'b0000000-0000-0000-0003-000000000011', 'c0000000-0000-0000-0000-000000000008', 'a1000000-0000-0000-0000-000000000001', 5, 5, 5, 5, 5, 'Autumn colours along the Ring were breathtaking. The safari tent was cozy as temperatures dropped. Bike hire was great for exploring - less traffic than summer. Breakfast basket was a lovely morning treat. Highly recommend autumn visits!', 'Ciara, autumn is indeed our hidden gem season! The colours are spectacular. Thanks for appreciating the quieter time of year.', 9, NOW() - INTERVAL '3 months 10 days', NOW() - INTERVAL '3 months 6 days'),

('e0000000-0000-0000-0004-000000000005', 'b0000000-0000-0000-0004-000000000007', 'c0000000-0000-0000-0000-000000000008', 'a1000000-0000-0000-0000-000000000007', 5, 5, 5, 5, 5, 'October visit was spectacular. Dramatic skies and moody mountains. The wood-burning stove made the tent feel like home. Less crowded than summer. Will definitely be back - might try the kayaking next time!', NULL, 6, NOW() - INTERVAL '2 months 7 days', NOW() - INTERVAL '2 months 4 days');

-- Roundstone Harbour View Reviews (Campsite c0000000-0000-0000-0000-000000000010)
INSERT INTO reviews (id, booking_id, campsite_id, user_id, rating, cleanliness_rating, facilities_rating, location_rating, value_rating, comment, owner_response, helpful_count, created_at, updated_at) VALUES
('e0000000-0000-0000-0002-000000000014', 'b0000000-0000-0000-0002-000000000024', 'c0000000-0000-0000-0000-000000000010', 'a1000000-0000-0000-0000-000000000017', 5, 5, 5, 5, 5, 'Seafood heaven! The harbour location is stunning. Watching fishermen bring in their catch then having it for dinner - incredible! The lobster experience was unforgettable. Photography tour at sunset was magical. Worth every penny.', 'Tadhg, as a fellow fishing enthusiast, I knew you would appreciate the fresh catch! The lobster experience is very special. See you again!', 21, NOW() - INTERVAL '4 months 19 days', NOW() - INTERVAL '4 months 15 days'),

('e0000000-0000-0000-0002-000000000015', 'b0000000-0000-0000-0002-000000000025', 'c0000000-0000-0000-0000-000000000010', 'a1000000-0000-0000-0000-000000000019', 5, 5, 5, 5, 4, 'Writer retreat at the Fisherman Cottage was perfect. The harbour views were endlessly inspiring. Sound of waves and seabirds - pure peace. Seafood dinner was exceptional. Slightly isolated for some but perfect for creative work.', 'So glad the cottage inspired your writing Oisin! We love hosting creatives. The isolation is intentional - no distractions!', 12, NOW() - INTERVAL '4 months 7 days', NOW() - INTERVAL '4 months 3 days'),

('e0000000-0000-0000-0003-000000000006', 'b0000000-0000-0000-0003-000000000013', 'c0000000-0000-0000-0000-000000000010', 'a1000000-0000-0000-0000-000000000017', 5, 5, 5, 5, 5, 'September seafood weekend was fantastic! The wine and cheese evening on the harbour was a highlight. Siobhan knows her local produce. Less busy than summer but weather was perfect. Already planning our next visit.', 'Tadhg! Lovely to have you back. September is such a sweet spot - good weather, fewer crowds. See you for the oyster season!', 8, NOW() - INTERVAL '3 months 7 days', NOW() - INTERVAL '3 months 4 days');

-- Giant's Causeway Camp Reviews (Campsite c0000000-0000-0000-0000-000000000013)
INSERT INTO reviews (id, booking_id, campsite_id, user_id, rating, cleanliness_rating, facilities_rating, location_rating, value_rating, comment, owner_response, helpful_count, created_at, updated_at) VALUES
('e0000000-0000-0000-0002-000000000016', 'b0000000-0000-0000-0002-000000000030', 'c0000000-0000-0000-0000-000000000013', 'a1000000-0000-0000-0000-000000000011', 4, 4, 4, 5, 5, 'Great base for exploring the Causeway Coast! Walking distance to the Giant''s Causeway itself. The visitor centre tickets included were a nice touch. Facilities are good quality. Evening campfires with views of the dramatic coastline were memorable.', 'Thanks Aisling! Being so close to the Causeway is our biggest asset. Glad you enjoyed the dramatic coast!', 15, NOW() - INTERVAL '4 months 20 days', NOW() - INTERVAL '4 months 15 days'),

('e0000000-0000-0000-0002-000000000017', 'b0000000-0000-0000-0002-000000000031', 'c0000000-0000-0000-0000-000000000013', 'a1000000-0000-0000-0000-000000000012', 5, 5, 4, 5, 5, 'Whiskey trail trip was brilliant! The Bushmills tour was excellent and having accommodation so close meant we could enjoy the tasting properly. The Causeway Pod was comfortable and warm. Would highly recommend the distillery experience!', 'Cheers Cillian! The Bushmills tour pairs perfectly with a stay here. Responsible whiskey touring at its finest!', 11, NOW() - INTERVAL '4 months 8 days', NOW() - INTERVAL '4 months 5 days'),

('e0000000-0000-0000-0002-000000000018', 'b0000000-0000-0000-0002-000000000032', 'c0000000-0000-0000-0000-000000000013', 'a1000000-0000-0000-0000-000000000015', 4, 4, 4, 5, 5, 'Mobile home was perfect for our large family. Kids loved the Giant''s Causeway - spent hours climbing on the columns. The coastal walk was beautiful but windy! Shop on site was convenient. Good value for the location.', 'Marie, glad the family enjoyed the Causeway! The wind is part of the character up here. Thanks for visiting!', 9, NOW() - INTERVAL '3 months 29 days', NOW() - INTERVAL '3 months 25 days'),

('e0000000-0000-0000-0003-000000000007', 'b0000000-0000-0000-0003-000000000016', 'c0000000-0000-0000-0000-000000000013', 'a1000000-0000-0000-0000-000000000011', 5, 5, 5, 5, 5, 'September Causeway visit was perfect timing. Fewer tourists but still good weather. The Giant Pod was cozy and had great views. Coastal walk guide was knowledgeable and showed us hidden spots. Highly recommend off-season visits!', 'Aisling, you discovered our secret - September is magical here! The guided walks really do show you the hidden gems. Welcome back anytime!', 13, NOW() - INTERVAL '3 months 16 days', NOW() - INTERVAL '3 months 12 days'),

('e0000000-0000-0000-0004-000000000006', 'b0000000-0000-0000-0004-000000000009', 'c0000000-0000-0000-0000-000000000013', 'a1000000-0000-0000-0000-000000000012', 4, 4, 4, 5, 5, 'Autumn Causeway visit was dramatic! Stormy skies made for incredible photos. The pod was warm and comfortable despite the weather. Declan is a great host with lots of local knowledge. Would come back in winter for more dramatic weather!', 'Thanks Cillian! Storm watching here is pretty special. Winter visits are wild but unforgettable. See you then!', 7, NOW() - INTERVAL '2 months 3 days', NOW() - INTERVAL '2 months'),

('e0000000-0000-0000-0005-000000000004', 'b0000000-0000-0000-0005-000000000008', 'c0000000-0000-0000-0000-000000000013', 'a1000000-0000-0000-0000-000000000011', 5, 5, 5, 5, 5, 'November Causeway trip was magical! Dramatic Atlantic storms, cozy pod, and hardly any other tourists. The Bushmills tour warmed us up nicely. This place is even better in the off-season. Already planning a winter return!', NULL, 5, NOW() - INTERVAL '1 month 17 days', NOW() - INTERVAL '1 month 14 days');

-- Dingle Peninsula B&B Reviews (Campsite c0000000-0000-0000-0000-000000000012)
INSERT INTO reviews (id, booking_id, campsite_id, user_id, rating, cleanliness_rating, facilities_rating, location_rating, value_rating, comment, owner_response, helpful_count, created_at, updated_at) VALUES
('e0000000-0000-0000-0002-000000000019', 'b0000000-0000-0000-0002-000000000028', 'c0000000-0000-0000-0000-000000000012', 'a1000000-0000-0000-0000-000000000013', 5, 5, 5, 5, 4, 'Dingle food trail stay was fantastic! Niamh recommended the best restaurants and we ate like royalty. The Full Irish was the perfect start to each day. Bay view room was gorgeous. Dolphin trip was a lovely bonus. Pricier than expected but quality is top notch.', 'Emma, so glad you experienced the best of Dingle food! We do love our local produce here. Thanks for trusting my recommendations!', 14, NOW() - INTERVAL '4 months 16 days', NOW() - INTERVAL '4 months 12 days'),

('e0000000-0000-0000-0002-000000000020', 'b0000000-0000-0000-0002-000000000029', 'c0000000-0000-0000-0000-000000000012', 'a1000000-0000-0000-0000-000000000001', 5, 5, 5, 5, 5, 'Slea Head Suite was perfect for our family. The views of Dingle Bay from the room were stunning. Niamh''s packed lunches were lifesavers on the Slea Head Drive. Evening meal was home-cooked perfection. Kids still talk about it!', 'Ciara, the Slea Head Drive is such an adventure! So happy the kids enjoyed it. The packed lunches are my secret pride. Come back anytime!', 12, NOW() - INTERVAL '4 months 2 days', NOW() - INTERVAL '3 months 28 days'),

('e0000000-0000-0000-0003-000000000008', 'b0000000-0000-0000-0003-000000000015', 'c0000000-0000-0000-0000-000000000012', 'a1000000-0000-0000-0000-000000000015', 4, 5, 4, 5, 5, 'Blasket Islands room had beautiful views. Niamh was wonderfully helpful with ferry bookings to the islands. The breakfast kept us going all day! Facilities are traditional but charming. Great value for the location.', 'Marie, glad you made it to the Blaskets! They are such a special place. Thanks for appreciating our traditional charm!', 8, NOW() - INTERVAL '3 months 2 days', NOW() - INTERVAL '2 months 28 days'),

('e0000000-0000-0000-0004-000000000007', 'b0000000-0000-0000-0004-000000000008', 'c0000000-0000-0000-0000-000000000012', 'a1000000-0000-0000-0000-000000000001', 5, 5, 5, 5, 5, 'October Dingle break was perfect. Fewer tourists, moody skies, cozy B&B. Niamh''s homemade brown bread is heavenly. The evening meal option was so convenient after long days exploring. Will definitely return!', 'Ciara! October in Dingle is magical. The brown bread recipe is my grandmother''s - glad you appreciate it! See you next time!', 10, NOW() - INTERVAL '2 months 14 days', NOW() - INTERVAL '2 months 10 days'),

('e0000000-0000-0000-0005-000000000005', 'b0000000-0000-0000-0005-000000000007', 'c0000000-0000-0000-0000-000000000012', 'a1000000-0000-0000-0000-000000000013', 5, 5, 5, 5, 5, 'Thanksgiving Dingle trip was wonderful! Niamh made us feel so welcome even though it''s not an Irish holiday. The Slea Head Suite views were dramatic in November weather. Evening meals were comforting after cold days. A home away from home!', 'Emma, we love welcoming American guests for Thanksgiving! You brought such lovely energy. See you next year perhaps?', 6, NOW() - INTERVAL '1 month', NOW() - INTERVAL '25 days');

-- Connemara Retreat Reviews (Campsite c0000000-0000-0000-0000-000000000005)
INSERT INTO reviews (id, booking_id, campsite_id, user_id, rating, cleanliness_rating, facilities_rating, location_rating, value_rating, comment, owner_response, helpful_count, created_at, updated_at) VALUES
('e0000000-0000-0000-0002-000000000021', 'b0000000-0000-0000-0002-000000000013', 'c0000000-0000-0000-0000-000000000005', 'a1000000-0000-0000-0000-000000000006', 5, 5, 5, 5, 5, 'The Mountain View Cottage was absolutely perfect! Turf fire burning, rain on the windows, Twelve Bens in the distance - pure Connemara magic. The guided mountain walk was challenging but rewarding. Mary made us feel so welcome. Already planning our return!', 'Thank you Padraig! You captured Connemara perfectly. The Twelve Bens were showing off for you! See you soon.', 17, NOW() - INTERVAL '4 months 13 days', NOW() - INTERVAL '4 months 10 days'),

('e0000000-0000-0000-0002-000000000022', 'b0000000-0000-0000-0002-000000000014', 'c0000000-0000-0000-0000-000000000005', 'a1000000-0000-0000-0000-000000000009', 5, 5, 4, 5, 5, 'Artist Cabin was inspirational! Spent 3 days painting with incredible light. The isolation is perfect for creative work. Fishing gear hire was a lovely bonus for when I needed a break. Would highly recommend for artists and writers.', 'Roisin, we would love to see your paintings! The cabin light is special - many artists say the same. Creativity flows here!', 11, NOW() - INTERVAL '4 months 3 days', NOW() - INTERVAL '4 months'),

('e0000000-0000-0000-0003-000000000009', 'b0000000-0000-0000-0003-000000000008', 'c0000000-0000-0000-0000-000000000005', 'a1000000-0000-0000-0000-000000000005', 5, 5, 5, 5, 5, 'Lakeside Cottage in autumn was breathtaking! Fishing right on our doorstep. The turf delivery service was perfect - nothing beats that smell. Mary''s welcome grocery pack saved us a trip to town. Pure tranquility.', 'Niamh, autumn fishing on the lake is special. The turf fire in the cottage... proper Connemara! Thanks for appreciating the simple things.', 9, NOW() - INTERVAL '3 months 15 days', NOW() - INTERVAL '3 months 12 days'),

('e0000000-0000-0000-0005-000000000006', 'b0000000-0000-0000-0005-000000000005', 'c0000000-0000-0000-0000-000000000005', 'a1000000-0000-0000-0000-000000000006', 5, 5, 5, 5, 5, 'November cottage retreat was exactly what we needed. Cozy turf fires, misty mountains, complete peace. Mary is the perfect host - helpful but gives you space. The welcome pack was so thoughtful. Heaven on earth!', 'Padraig, so glad you found the peace you were seeking. November in Connemara has a special stillness. See you again!', 7, NOW() - INTERVAL '1 month 13 days', NOW() - INTERVAL '1 month 10 days'),

('e0000000-0000-0000-0006-000000000001', 'b0000000-0000-0000-0006-000000000008', 'c0000000-0000-0000-0000-000000000005', 'a1000000-0000-0000-0000-000000000005', 5, 5, 5, 5, 5, 'Christmas week in the Lakeside Cottage was magical! Snow on the Twelve Bens, turf fire crackling, complete escapism. The guided walk on Christmas morning was unforgettable. Best Christmas ever!', 'What a joy to have you for Christmas Niamh! The snow was a rare gift. The morning walk is a tradition here - glad you joined us!', 13, NOW() - INTERVAL '2 days', NOW() - INTERVAL '1 day');

-- Burren Camping Reviews (Campsite c0000000-0000-0000-0000-000000000011)
INSERT INTO reviews (id, booking_id, campsite_id, user_id, rating, cleanliness_rating, facilities_rating, location_rating, value_rating, comment, owner_response, helpful_count, created_at, updated_at) VALUES
('e0000000-0000-0000-0002-000000000023', 'b0000000-0000-0000-0002-000000000026', 'c0000000-0000-0000-0000-000000000011', 'a1000000-0000-0000-0000-000000000008', 4, 4, 4, 5, 5, 'Unique camping experience in the Burren landscape! The limestone terrain is like nowhere else. Farm fresh eggs for breakfast were delicious. Basic facilities but clean and functional. Great base for Cliffs of Moher day trip. Excellent value!', 'Thanks Dermot! The Burren is indeed unique - glad you appreciated it. Our hens were happy to provide breakfast! Come back anytime.', 12, NOW() - INTERVAL '4 months 23 days', NOW() - INTERVAL '4 months 20 days'),

('e0000000-0000-0000-0002-000000000024', 'b0000000-0000-0000-0002-000000000027', 'c0000000-0000-0000-0000-000000000011', 'a1000000-0000-0000-0000-000000000014', 4, 4, 4, 5, 5, 'Cliffs of Moher shuttle was so convenient! Camping in the Burren was an adventure. The limestone landscape is otherworldly. Farm shop had great local produce. Would recommend for budget travellers who want authentic Irish countryside.', 'Hans, the shuttle saves everyone the parking hassle at the Cliffs! Glad you enjoyed our unique landscape. Welcome back!', 8, NOW() - INTERVAL '4 months 11 days', NOW() - INTERVAL '4 months 8 days'),

('e0000000-0000-0000-0003-000000000010', 'b0000000-0000-0000-0003-000000000014', 'c0000000-0000-0000-0000-000000000011', 'a1000000-0000-0000-0000-000000000008', 4, 4, 4, 5, 5, 'Autumn Burren walk was fascinating! Liam knows every wildflower and rock formation. The geology here is incredible. Fresh farm milk for tea was a treat. Simple camping but the location makes up for any lack of luxury.', 'Dermot! Your enthusiasm for botany was wonderful. The Burren flora is special - autumn reveals different beauties. See you again!', 6, NOW() - INTERVAL '3 months 15 days', NOW() - INTERVAL '3 months 12 days');

-- Clifden Eco Camp Reviews (Campsite c0000000-0000-0000-0000-000000000009)
INSERT INTO reviews (id, booking_id, campsite_id, user_id, rating, cleanliness_rating, facilities_rating, location_rating, value_rating, comment, owner_response, helpful_count, created_at, updated_at) VALUES
('e0000000-0000-0000-0002-000000000025', 'b0000000-0000-0000-0002-000000000022', 'c0000000-0000-0000-0000-000000000009', 'a1000000-0000-0000-0000-000000000010', 4, 4, 5, 5, 5, 'Sky Road Yurt was a great base for cycling! The eco-friendly approach is genuine - solar and wind powered. Bike rental made exploring easy. Walking distance to Clifden for supplies and pubs. Good value for the sustainability-minded traveller.', 'Thanks Eoin! Your cycling enthusiasm was impressive - the Sky Road is a challenge! Glad the eco credentials measured up. Pedal back soon!', 10, NOW() - INTERVAL '4 months 16 days', NOW() - INTERVAL '4 months 12 days'),

('e0000000-0000-0000-0002-000000000026', 'b0000000-0000-0000-0002-000000000023', 'c0000000-0000-0000-0000-000000000009', 'a1000000-0000-0000-0000-000000000005', 4, 4, 4, 5, 5, 'Eco Pod was cozy and comfortable. Love that it is wind and solar powered. Hot water bottle on cool nights was a nice touch. Walking poles hire was useful for the hills. Great location near Clifden. Would recommend for eco-conscious travellers.', 'Niamh, the hot water bottles are essential for Irish nights! Thanks for supporting sustainable tourism. Every little helps!', 7, NOW() - INTERVAL '4 months 5 days', NOW() - INTERVAL '4 months 2 days'),

('e0000000-0000-0000-0003-000000000011', 'b0000000-0000-0000-0003-000000000012', 'c0000000-0000-0000-0000-000000000009', 'a1000000-0000-0000-0000-000000000010', 5, 4, 5, 5, 5, 'September cycling trip from the Atlantic Yurt was brilliant! Less busy than summer. The yurt was warm despite cool nights. Bike rental quality was excellent. Siobhan is passionate about sustainability. Will definitely return!', 'Eoin! September cycling legend! The quieter roads make such a difference. See you for more adventures!', 8, NOW() - INTERVAL '3 months 20 days', NOW() - INTERVAL '3 months 17 days');
